function returnText(locale, key, values = {}) {
  return RETURN_COPY[locale][key].replace(/\{(\w+)\}/g, (token, name) => Object.hasOwn(values, name) ? String(values[name]) : token);
}

// src/lib/return-visits/sky-calendar.ts
function skyCalendarEvents(locale) {
  const moons = sky_default.moons.filter((moon) => moon.type === "new" || moon.type === "full").map((moon) => ({
    id: `${moon.type}-moon-${moon.at}`,
    start: moon.at,
    summary: returnText(locale, moon.type === "new" ? "newMoon" : "fullMoon"),
    description: returnText(locale, "calendarEventNote"),
    url: "https://zodiacs.org/methodology/"
  }));
  const peaks = eclipses_default.eclipses.map((eclipse) => ({
    id: `${eclipse.type}-eclipse-${eclipse.peak}`,
    start: eclipse.peak,
    summary: returnText(locale, eclipse.type === "solar" ? "solarEclipse" : "lunarEclipse"),
    description: returnText(locale, "eclipseNote"),
    url: "https://zodiacs.org/eclipses/"
  }));
  const retrogrades = sky_default.retrogrades.map((window) => ({
    id: `${window.planet}-retrograde-${window.from}`,
    start: window.from,
    end: window.to,
    summary: returnText(locale, "retrogradeWindow", { planet: planetLabel(locale, window.planet) }),
    description: returnText(locale, "retrogradeNote"),
    url: "https://zodiacs.org/retrogrades/"
  }));
  return [...moons, ...peaks, ...retrogrades].sort((a, b) => String(a.start).localeCompare(String(b.start)));
}

